//! Script Kit's bundled Lucide icon SVGs, served at `icons/<name>.svg`.
//!
//! Registered after gpui-kit's own assets so kit components keep their icons,
//! while every Lucide name Script Kit accepts (including renamed legacy names)
//! still resolves. See `src/icons/lucide_catalog.rs`.

use gpui::{AssetSource, Result, SharedString};
use rust_embed::RustEmbed;
use std::borrow::Cow;

#[derive(RustEmbed)]
#[folder = "assets"]
#[include = "icons/**/*.svg"]
pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        if path.is_empty() {
            return Ok(None);
        }
        Ok(Self::get(path).map(|file| file.data))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        Ok(Self::iter()
            .filter_map(|p| p.starts_with(path).then(|| p.into()))
            .collect())
    }
}
